package l4tls

// JA test vectors derived from FoxIO-LLC/ja4
// (https://github.com/FoxIO-LLC/ja4), commit
// f7bf03ae81a8b62297ae0be5ef7c7bcfc4705a25, retrieved 2026-05-20.
//
// JA4 (TLS client fingerprinting) is BSD-3-Clause; see
// testdata/LICENSE-FoxIO-JA4.txt. (The rest of the FoxIO JA4+ suite is
// under a different license and is NOT used here.)
//
// ClientHello byte fixtures are raw TLS protocol captures extracted
// from FoxIO's published sample pcaps; expected JA4/JA4_r values are
// FoxIO's own checked-in reference outputs
// (python/test/testdata/<pcap>.json). Expected JA3 values are from the
// canonical Salesforce-derived pyja3 reference run on the same capture.
//
// ClientHello holds the handshake-message bytes (TLS record header
// stripped, starting with 0x01) — exactly what parseRawClientHello
// consumes. Run them through the real parser so these vectors exercise
// parser + fingerprint together.

type JAVector struct {
	Name          string
	ClientHello   string // hex of the raw ClientHello handshake-message bytes
	ExpectedJA3   string // canonical JA3 (md5 hex, GREASE filtered); "" = skip JA3 assertion
	ExpectedJA4   string // default JA4 (ja4_a_ja4_b_ja4_c); "" = skip JA4 assertion
	ExpectedJA4_r string // raw pre-hash JA4 string, for debugging (optional)
	Source        string // provenance
}

var JAVectors = []JAVector{
	{
		// Firefox, TLS1.3, NO GREASE, single ClientHello, SNI + ALPN h2.
		// Anchor vector. pyja3 (no GREASE present) and our JA3 agree.
		Name:          "firefox_tls13_no_grease",
		ClientHello:   "",
		ExpectedJA3:   "579ccef312d18482fc42e2b822ca2430",
		ExpectedJA4:   "t13d1715h2_5b57614c22b0_3d5424432f57",
		ExpectedJA4_r: "t13d1715h2_002f,0035,009c,009d,1301,1302,1303,c009,c00a,c013,c014,c02b,c02c,c02f,c030,cca8,cca9_0005,000a,000b,000d,0015,0017,001c,0022,0023,002b,002d,0033,ff01_0403,0503,0603,0804,0805,0806,0401,0501,0601,0203,0201",
		Source:        "FoxIO pcap/tls12.pcap stream 0 (srcport 36372, contile.services.mozilla.com) @ f7bf03a; JA4=FoxIO testdata, JA3=pyja3",
	},
	{
		// Chrome, TLS1.3, WITH GREASE (ciphers/exts/curves/sigalgs all carry
		// 0x?a?a markers), SNI + ALPN h2. Proves JA4 GREASE-stripping. pyja3
		// strips GREASE, so its JA3 matches our canonical (GREASE-filtered) JA3.
		Name:          "chrome_tls13_grease_alpn_h2",
		ClientHello:   "",
		ExpectedJA3:   "1c258ebef8eee2dfa3df6d8d07285af9",
		ExpectedJA4:   "t13d1516h2_8daaf6152771_e5627efa2ab1",
		ExpectedJA4_r: "t13d1516h2_002f,0035,009c,009d,1301,1302,1303,c013,c014,c02b,c02c,c02f,c030,cca8,cca9_0005,000a,000b,000d,0012,0015,0017,001b,0023,002b,002d,0033,4469,ff01_0403,0804,0401,0503,0805,0501,0806,0601",
		Source:        "FoxIO pcap/tls-sni.pcapng stream 0 (srcport 50112, clientservices.googleapis.com) @ f7bf03a; JA4=FoxIO testdata, JA3=pyja3 (lossless pcapng->pcap conversion)",
	},
	{
		// Chrome, TLS1.3, WITH GREASE, SNI but NO ALPN extension -> JA4 ALPN
		// field "00" (t13d151400). dstport 5228 (mtalk), so pyja3 emitted no
		// JA3 for this stream -> JA3 skipped; JA4-only.
		Name:          "chrome_tls13_grease_no_alpn",
		ClientHello:   "",
		ExpectedJA3:   "",
		ExpectedJA4:   "t13d151400_8daaf6152771_de4a06bb82e3",
		ExpectedJA4_r: "t13d151400_002f,0035,009c,009d,1301,1302,1303,c013,c014,c02b,c02c,c02f,c030,cca8,cca9_0005,000a,000b,000d,0012,0015,0017,001b,0023,002b,002d,0033,ff01_0403,0804,0401,0503,0805,0501,0806,0601",
		Source:        "FoxIO pcap/tls-sni.pcapng stream 6 (srcport 50123, mtalk.google.com:5228) @ f7bf03a; JA4=FoxIO testdata, JA3 unavailable from pyja3",
	},
	{
		// Chrome, TLS1.3, WITH GREASE, has the extra extension 0x0029
		// (pre_shared_key) -> distinct JA4_c (17 exts, t13d1517h1) and a
		// different JA3 ext list. pyja3 strips GREASE; JA3 asserted.
		Name:          "chrome_tls13_grease_ext_psk",
		ClientHello:   "",
		ExpectedJA3:   "e2ce5351e791ab3c3f63764919302aca",
		ExpectedJA4:   "t13d1517h1_8daaf6152771_6cdcb247c39b",
		ExpectedJA4_r: "t13d1517h1_002f,0035,009c,009d,1301,1302,1303,c013,c014,c02b,c02c,c02f,c030,cca8,cca9_0005,000a,000b,000d,0012,0015,0017,001b,0023,0029,002b,002d,0033,4469,ff01_0403,0804,0401,0503,0805,0501,0806,0601",
		Source:        "FoxIO pcap/tls-sni.pcapng stream 31 (srcport 50153, edge-chat.facebook.com) @ f7bf03a; JA4=FoxIO testdata, JA3=pyja3 (lossless pcapng->pcap conversion)",
	},
	{
		// TLS1.2 client (curl/cloudflare), large cipher list (t12d4605h2),
		// ALPN h2. NO GREASE. Captured over loopback (null link layer) so pyja3
		// (Ethernet-only via dpkt.pcap) emits nothing -> JA3 skipped; JA4-only.
		Name:          "tls12_alpn_h2",
		ClientHello:   "",
		ExpectedJA3:   "",
		ExpectedJA4:   "t12d4605h2_85626a9a5f7f_aaf95bb78ec9",
		ExpectedJA4_r: "t12d4605h2_0004,0005,000a,0016,002f,0033,0035,0039,003c,003d,0041,0045,0067,006b,0081,0084,0088,009c,009d,009e,009f,00ba,00be,00c0,00c4,00ff,c007,c008,c009,c00a,c011,c012,c013,c014,c023,c024,c027,c028,c02b,c02c,c02f,c030,cca8,cca9,ccaa,ff85_000a,000b,000d_0601,0603,efef,0501,0503,0401,0403,eeee,eded,0301,0303,0201,0203",
		Source:        "FoxIO pcap/tls-alpn-h2.pcap stream 0 (srcport 64034, www.cloudflare.com) @ f7bf03a; JA4=FoxIO testdata, JA3 unavailable from pyja3 (loopback link layer)",
	},
	{
		// Chrome, TLS1.3, WITH GREASE. Same wire bytes as chrome_tls13_grease_alpn_h2
		// EXCEPT the first ALPN protocol byte is non-ASCII (0x02baad vs 0x026832)
		// -> JA4 ALPN field "99" (t13d151699). The ALPN edge case. JA3 ignores
		// ALPN so the JA3 digest is identical to the h2 sibling; pyja3 confirms.
		Name:          "chrome_tls13_grease_nonascii_alpn",
		ClientHello:   "",
		ExpectedJA3:   "1c258ebef8eee2dfa3df6d8d07285af9",
		ExpectedJA4:   "t13d151699_8daaf6152771_e5627efa2ab1",
		ExpectedJA4_r: "t13d151699_002f,0035,009c,009d,1301,1302,1303,c013,c014,c02b,c02c,c02f,c030,cca8,cca9_0005,000a,000b,000d,0012,0015,0017,001b,0023,002b,002d,0033,4469,ff01_0403,0804,0401,0503,0805,0501,0806,0601",
		Source:        "FoxIO pcap/tls-non-ascii-alpn.pcapng stream 0 (srcport 50112, clientservices.googleapis.com) @ f7bf03a; JA4=FoxIO testdata, JA3=pyja3 (lossless pcapng->pcap conversion)",
	},
}
